import re

from django.core import validators
from django.utils.deconstruct import deconstructible
from django.utils.translation import gettext_lazy as _


@deconstructible
class ASCIIUsernameValidator(validators.RegexValidator):
    regex = r"^[\w.@+-]+\Z"
    message = _(
        "Masukkan nama pengguna yang valid. Nilai ini hanya boleh berisi huruf kecil tanpa aksen a-z "
        "dan huruf besar A-Z, angka, dan karakter @/./+/-/_."
    )
    flags = re.ASCII


@deconstructible
class UnicodeUsernameValidator(validators.RegexValidator):
    regex = r"^[\w.@+-]+\Z"
    message = _(
        "Masukkan nama pengguna yang valid. Nilai ini hanya boleh berisi huruf, "
        "angka, dan karakter @/./+/-/_."
    )
    flags = 0
